const rss_feeds = [
  "https://hnrss.org/frontpage",
  "https://feeds.bbci.co.uk/news/technology/rss.xml"
];

const topics = [
  "agentic workflows",
  "model context protocol",
  "vector databases",
  "prompt injection",
  "postgres embeddings"
];

const config = {
  cache_ttl_minutes: 90,
  dedupe_ttl_days: 21,
  min_score: 6,
  max_items_total: 45,
  max_per_source: 16,
  max_per_topic: 8,
  enable_llm_summary: true,
  timeout_ms: 12000,
  GITHUB_TOKEN: $env.GITHUB_TOKEN || "",
  ZAI_API_KEY: $env.ZAI_API_KEY || "",
  ZAI_BASE_URL: $env.ZAI_BASE_URL || "https://api.z.ai/api/paas/v4",
  ZAI_MODEL: $env.ZAI_MODEL || "glm-5"
};

const st = $getWorkflowStaticData('global');
st.runs = (st.runs || 0) + 1;

return [{ json: { rss_feeds, topics, config, run_id: 'run_' + st.runs } }];

const items = [];
for (const item of $input.all()) {
  const data = item.json;
  const feedItems = Array.isArray(data) ? data : (data.items || []);
  for (const entry of feedItems) {
    items.push({
      json: {
        source: "rss",
        topic: null,
        title: entry.title || "Untitled",
        url: entry.link || entry.guid || "",
        published_at: entry.pubDate || entry.date || null,
        raw_score: 5,
        score: 5,
        summary_raw: null,
        summary: null,
        meta: { author: null, venue: null, cached: false }
      }
    });
  }
}
return items;

const topic = $json.topic;
const config = $json.config;
const st = $getWorkflowStaticData('global');
if (!st.cache) st.cache = {};

const ttl_ms = config.cache_ttl_minutes * 60 * 1000;
const now = Date.now();

// PRUNE
for (const k in st.cache) {
  if (now - st.cache[k].ts_epoch_ms > ttl_ms) {
    delete st.cache[k];
  }
}

if (st.cache[topic]) {
  return [{ json: { topic, config, cache_hit: true, cached_items: st.cache[topic].items } }];
} else {
  return [{ json: { topic, config, cache_hit: false } }];
}

const cached = $input.first().json.cached_items;
const out = [];
for (const item of cached) {
  const cp = JSON.parse(JSON.stringify(item));
  if (!cp.meta) cp.meta = {};
  cp.meta.cached = true;
  out.push({ json: cp });
}
return out;

const topic = $('Cache Gate').first().json.topic;
const items = [];
for (const item of $input.all()) {
  const hits = item.json.hits || [];
  for (const h of hits) {
    items.push({
      json: {
        source: "hn",
        topic,
        title: h.title || "",
        url: h.url || ('https://news.ycombinator.com/item?id=' + h.objectID),
        published_at: h.created_at || null,
        raw_score: (h.points || 0) + (h.num_comments || 0),
        score: 0,
        summary_raw: null,
        summary: null,
        meta: { author: h.author, venue: null, cached: false }
      }
    });
  }
}
return items;

