const topic = $('Cache Gate').first().json.topic;
const items = [];
const data = $input.first().json;
const repos = data.items || [];
for (const r of repos) {
  items.push({
    json: {
      source: "github",
      topic,
      title: r.full_name || r.name,
      url: r.html_url,
      published_at: r.created_at || r.updated_at || null,
      raw_score: (r.stargazers_count || 0) + (r.forks_count || 0),
      score: 0,
      summary_raw: r.description || null,
      summary: null,
      meta: { author: r.owner?.login || null, venue: "GitHub", cached: false }
    }
  });
}
return items;

const topic = $('Cache Gate').first().json.topic;
const items = [];
const data = $input.first().json;
const works = data.message?.items || [];
for (const w of works) {
  items.push({
    json: {
      source: "crossref",
      topic,
      title: w.title?.[0] || "Untitled",
      url: w.URL || "",
      published_at: w.published?.['date-parts']?.[0]?.join('-') || null,
      raw_score: 20 + (w['is-referenced-by-count'] || 0),
      score: 0,
      summary_raw: null,
      summary: null,
      meta: { author: null, venue: w['container-title']?.[0] || null, cached: false }
    }
  });
}
return items;

const topic = $('Cache Gate').first().json.topic;
const items = [];
const data = $input.first().json;
const results = data.results || [];
for (const r of results) {
  items.push({
    json: {
      source: "openalex",
      topic,
      title: r.title || "Untitled",
      url: r.primary_location?.source?.homepage_url || r.id,
      published_at: r.publication_date || null,
      raw_score: 15 + (r.cited_by_count || 0),
      score: 0,
      summary_raw: null,
      summary: null,
      meta: { author: null, venue: r.primary_location?.source?.display_name || "OpenAlex", cached: false }
    }
  });
}
return items;

const topic = $('Cache Gate').first().json.topic;
const st = $getWorkflowStaticData('global');
if (!st.cache) st.cache = {};

const normalizedItems = $input.all().map(x => x.json);
st.cache[topic] = { ts_epoch_ms: Date.now(), items: normalizedItems };

return normalizedItems.map(x => {
  const cp = JSON.parse(JSON.stringify(x));
  if (!cp.meta) cp.meta = {};
  cp.meta.cached = false;
  return { json: cp };
});

const init = $('Init').first().json;
const config = init.config;
const st = $getWorkflowStaticData('global');
if (!st.seen) st.seen = {};

// PRUNE SEEN
const dedupe_ms = config.dedupe_ttl_days * 24 * 60 * 60 * 1000;
const now = Date.now();
for (const k in st.seen) {
  if (now - st.seen[k].ts > dedupe_ms) delete st.seen[k];
}

const bonusMap = { hn: 3, github: 2, crossref: 1, openalex: 1, rss: 0 };

let items = $input.all().map(x => x.json);

// CANONICALIZE & DEDUPE
items = items.filter(item => {
  if (!item.url) return false;
  try {
    const u = new URL(item.url.toLowerCase());
    u.searchParams.forEach((v, k) => { if (k.startsWith('utm_')) u.searchParams.delete(k); });
    u.pathname = u.pathname.replace(/\/$/, '');
    const canon = u.href;
    if (st.seen[canon]) return false;
    st.seen[canon] = { ts: now };
    item.url = canon;
    return true;
  } catch (e) { return false; }
});

// SCORE
items.forEach(item => {
  let age = 96;
  if (item.published_at) {
    try { age = (now - new Date(item.published_at).getTime()) / 36e5; } catch(e) {}
  }
  const bonus = bonusMap[item.source] || 0;
  item.score = Math.max(0, item.raw_score - 0.12 * age) + bonus;
});

items = items.filter(x => x.score >= config.min_score);
items.sort((a, b) => b.score - a.score);

// DIVERSITY CAPS
const srcCnt = {};
const topCnt = {};
items = items.filter(item => {
  const sc = (srcCnt[item.source] || 0);
  const tc = item.topic ? (topCnt[item.topic] || 0) : 0;
  if (sc >= config.max_per_source || tc >= config.max_per_topic) return false;
  srcCnt[item.source] = sc + 1;
  if (item.topic) topCnt[item.topic] = tc + 1;
  return true;
});

items = items.slice(0, config.max_items_total);

const cacheGateItems = $items('Cache Gate');
const missCount = cacheGateItems ? cacheGateItems.filter(x => x.json.cache_hit === false).length : 0;
const cachedCount = items.filter(x => x.meta?.cached).length;

const stats = {
  total_items: items.length,
  cached_items: cachedCount,
  cache_miss_topics: missCount,
  api_calls_est: 4 * missCount
};

return [{ json: { config, topics: init.topics, stats, items, run_id: init.run_id, generated_at: new Date().toISOString() } }];

const base = $input.first().json;
const top12 = base.items.slice(0, 12);
const prompt = `Generate summaries for these items. Return STRICT JSON like {"summaries":[{"url":"...","summary":"1 sentence","tags":["t1"]}]}. Items:\n` + JSON.stringify(top12.map(i=>({u:i.url,t:i.title})), null, 2);

return [{ json: {
  __baseData: base,
  llm_body: { messages: [{ role: "user", content: prompt }] }
}}];

const prep = $('Prepare LLM').first().json;
const base = prep.__baseData;
const resp = $input.first().json;
let map = {};
try {
  const txt = resp.choices?.[0]?.message?.content;
  if (txt) {
    const d = JSON.parse(txt);
    if (Array.isArray(d.summaries)) {
      d.summaries.forEach(s => { if(s.url) map[s.url] = { sum: s.summary, tags: s.tags || [] }; });
    }
  }
} catch(e) {}

const items = base.items.map(item => {
  const hit = map[item.url];
  return {
    ...item,
    summary: hit ? hit.sum : (item.summary_raw || item.title),
    tags: hit ? hit.tags : []
  };
});

return [{ json: { ...base, items } }];

const base = $input.first().json;
const items = base.items.map(item => ({
  ...item,
  summary: item.summary_raw || item.title,
  tags: []
}));
return [{ json: { ...base, items } }];

const d = $input.first().json;
if (!d.items || !Array.isArray(d.items)) throw new Error('Missing items');
for (const item of d.items) {
  if (typeof item.url !== 'string' || !item.url) throw new Error('Invalid URL');
  if (typeof item.score !== 'number') throw new Error('Invalid score');
  if (item.url.includes('https://openalex.org/https://openalex.org')) throw new Error('Double URL');
}
return $input.all();

const d = $input.first().json;
const bySrc = {};
d.items.forEach(i => {
  if (!bySrc[i.source]) bySrc[i.source] = [];
  bySrc[i.source].push(i);
});
let md = `# GoldPulse ${d.run_id}\nGenerated at ${d.generated_at}\n\n`;
for (const src of Object.keys(bySrc).sort()) {
  md += `## ${src.toUpperCase()}\n`;
  bySrc[src].forEach(i => {
    md += `- [${i.score.toFixed(1)}] ${i.title} (${i.url})\n`;
    if (i.summary) md += `  _${i.summary}_\n`;
  });
  md += `\n`;
}
return [{ json: { ...d, digest_markdown: md } }];
